Info.StartupScript:
function autocomplete(inp, arr) {
  let currentFocus;
  inp.addEventListener("input", function(e) {
    let val = this.value;
    closeAllLists();
    if (!val) { return false;}
    currentFocus = -1;
    const listContainer = createListContainer(this);
    populateList(arr, val, listContainer);
  });
  //option for using arrow keys to select
  inp.addEventListener("keydown", function(e) {
    let x = document.getElementById(this.id + "autocomplete-list");
    if (x) x = x.getElementsByTagName("div");
    if (e.keyCode == 40) {
      currentFocus++;
      addActive(x);
    } else if (e.keyCode == 38) {
      currentFocus--;
      addActive(x);
    } else if (e.keyCode == 13) {
      e.preventDefault();
      if (currentFocus > -1) {
        if (x) x[currentFocus].click();
      }
    }
  });
  function addActive(x) {
    if (!x) return false;
    removeActive(x);
    if (currentFocus >= x.length) currentFocus = 0;
    if (currentFocus < 0) currentFocus = (x.length - 1);
    x[currentFocus].classList.add("autocomplete-active");
    const activeItems = document.getElementsByClassName("autocomplete-active");
    for (let i = 0; i < activeItems.length; i++) {
      activeItems[i].style.backgroundColor = "#eee";
    }
  }
  function removeActive(x) {
    for (let i = 0; i < x.length; i++) {
      x[i].classList.remove("autocomplete-active");
      x[i].style.backgroundColor = "#fff";
    }
  }
  //create dropdown
  function createListContainer(inputElement) {
    const container = document.createElement("DIV");
    container.setAttribute("id", inputElement.id + "autocomplete-list");
    container.setAttribute("class", "autocomplete-items");
    container.setAttribute("style", "position: absolute; border: 1px solid #d4d4d4; border-bottom: none; border-top: none; z-index: 99; background-color: #fff; overflow-y: auto; box-shadow: 0 4px 6px rgba(0, 0, 0, 0.1);");
    inputElement.after(container);
    return container;
  }
  function populateList(arr, val, container) {
    const topMatches = [];
    const otherMatches = [];
    const upperVal = val.toUpperCase();

    arr.forEach(item => {
        const [first, second] = item.map(str => str.toUpperCase());
        if (topMatches.length < 3 && (first.startsWith(upperVal) || second.startsWith(upperVal))) {
            topMatches.push(item);
        } else if (first.includes(upperVal) || second.includes(upperVal)) {
            otherMatches.push(item);
        }
    });
    // Insert top 3 matches that start with the input text
    topMatches.slice(0, 3).forEach(match => {
        const item = createListItem(match, val);
        container.appendChild(item);
    });
    // Insert the rest of the matches that contain the input text
    otherMatches.slice(0, 7).forEach(match => {
        const item = createListItem(match, val);
        container.appendChild(item);
    });
  }
  //create item to add to dropdown
  function createListItem(data, val) {
    const item = document.createElement("DIV");
    item.setAttribute("style", "padding: 10px; cursor: pointer; background-color: #fff; border-bottom: 1px solid #d4d4d4;");
    const displayText = `${data[0]}`.toUpperCase();
    item.innerHTML = highlightMatch(displayText, val);
    //item.innerHTML += `<input type="hidden" class="selection" name="${data[0]}_${data[1]}" value="${displayText}" data-label="${data[0]}" data-code="${data[1]}">`;
    item.innerHTML += `<input type='hidden' class='selection' name='${escapeHTMLchar(data[0])}_${escapeHTMLchar(data[1])}' value='${escapeHTMLchar(displayText)}' data-label='${escapeHTMLchar(data[0])}' data-code='${escapeHTMLchar(data[1])}'>`;
    item.addEventListener('mouseover', () => {item.style.backgroundColor = '#eee';});
    item.addEventListener('mouseout', () => {item.style.backgroundColor = '#fff';});
    item.addEventListener("click", function (e) {

      //SRC3498 - Erika updated occupation to Q33

      setQuestionValue("ESJ1_occupation", this.getElementsByTagName("input")[0].value);
      setQuestionValue("ESJ1_osca_label", this.getElementsByTagName("input")[0].dataset.label);
      setQuestionValue("ESJ1_osca_code", this.getElementsByTagName("input")[0].dataset.code);
      closeAllLists();
    });
    return item;
  }
  //bold matching substring in dropdown
  function highlightMatch(text, val) {
    const index = text.indexOf(val.toUpperCase());
    if (index === -1) {
      return text;
    } else if (index === 0) {
      return `<strong>${text.substring(0, val.length)}</strong>${text.substring(val.length)}`;
    } else {
      return `${text.substring(0, index)}<strong>${text.substring(index, index + val.length)}</strong>${text.substring(index + val.length)}`;
    }
  }
  function closeAllLists(elmnt) {
    let x = document.getElementsByClassName("autocomplete-items");
    for (let i = 0; i < x.length; i++) {
      if (elmnt != x[i] && elmnt != inp) {
        x[i].parentNode.removeChild(x[i]);
      }
    }
  }

  // -------------------------------------------------------------------------------------------------------------------------------------------
  //use this to assign values to variables, using JavaScript doesn't work
  function setQuestionValue(qId, val) {
    Confirmit.page.getQuestion(qId).setValue(val);
  }
  //hide dropdown on mouseclick
  document.addEventListener("click", function (e) {
    closeAllLists(e.target);
  });
}
