function maskES2() {
    var st = set();

    var codes = f('ES1').domainValues();

    for (var i = 0; i < codes.length; i++) {
        var code = codes[i];

        if (f('ES1').item(code).toBoolean()) {
            st.add(code);
        }
    }

    st = st.union(set('98', '99'))
    return st;
}
function maskES3() {
    var st2 = set();

    var codes = f('ES1').domainValues();

    for (var i = 0; i < codes.length; i++) {
        var code = codes[i];

        if (!f('ES1').item(code).toBoolean()) {
            st2.add(code);
        }
    }

    st2 = st2.union(set('96', '97', '98', '99'))
    return st2;
}

