function formatRole(txt)
{
    if (!txt) return "";

    // Remove trailing "role"
    txt = txt.replace(/\s+role\s*$/i, "").trim();

    // Add a/an
    var firstLetter = txt.charAt(0).toLowerCase();

    if ("aeiou".indexOf(firstLetter) >= 0)
    {
        txt = "an " + txt;
    }
    else
    {
        txt = "a " + txt;
    }

    return txt;
}

var es1Codes = f("ES1").categories();
var es1Labels = f("ES1").categoryLabels();

if (
    es1Codes.length == 1 &&
    parseInt(es1Codes[0], 10) >= 1 &&
    parseInt(es1Codes[0], 10) <= 96
)
{
    // Exactly one ES1 response, and it is code 1 to 96
    f("ES7_var").set(formatRole(es1Labels[0]));
}
else if (es1Codes.length > 1)
{
    // More than one ES1 response
    f("ES7_var").set(formatRole(f("ES2").valueLabel()));
}
else
{
    // No ES1 response, or the only response is outside codes 1 to 96
    f("ES7_var").set("");
}

