const qn_location = "ES16";
const qn_state = "q_state_ES16";
const qn_pcodeList = "pcode_list_ES16";

const mapping = {
  pcode: "finalPostcode_ES16",
  locality: "finalSuburb_ES16",
  state: "finalState_ES16",
  lga_pcprim: "finalLGA_pcprim_ES16",
  lga_locprim: "finalLGA_locprim_ES16",
  combined: "finalCombined_ES16",
  primary_src_market: "finalMarket_ES16",
  primary_src_market_name: "finalMarket_name_ES16",
  primary_remoteness: "finalRemoteness_ES16",
  seifa_irsd_2021: "finalSEIFA_irsd_ES16"
};

// Hide mapped fields
Object.values(mapping).forEach(id => {
  const el = document.getElementById(id);
  if (el) el.style.display = "none";
});

// Hide state - comment out if state is required
q_state_ES16.style.display = "none";

function autocomplete(inp, arr) {
  let currentFocus;

  inp.addEventListener("input", function () {
    closeAllLists();
    const val = this.value.trim();
    if (!val) return;

    currentFocus = -1;
    const container = createListContainer(this);
    const filteredArr = filterState(arr, Confirmit.page.getQuestion(qn_state).value);
    populateList(filteredArr, val, container);
  });

  inp.addEventListener("keydown", function (e) {
    let x = document.getElementById(this.id + "autocomplete-list");
    if (x) x = x.getElementsByTagName("div");
    if (e.keyCode === 40) currentFocus++, addActive(x);
    else if (e.keyCode === 38) currentFocus--, addActive(x);
    else if (e.keyCode === 13) {
      e.preventDefault();
      if (currentFocus > -1) {
        if (x) x[currentFocus].click();
      }
    }
  });

  function addActive(x) {
    if (!x) return;
    removeActive(x);
    if (currentFocus >= x.length) currentFocus = 0;
    if (currentFocus < 0) currentFocus = x.length - 1;
    x[currentFocus].classList.add("autocomplete-active");
    x[currentFocus].style.backgroundColor = "#eee";
  }

  function removeActive(x) {
    for (let i = 0; i < x.length; i++) {
      x[i].classList.remove("autocomplete-active");
      x[i].style.backgroundColor = "#fff";
    }
  }

  function createListContainer(inputElement) {
    const container = document.createElement("DIV");
    container.id = inputElement.id + "autocomplete-list";
    container.className = "autocomplete-items";
    container.style.cssText = `
      position:absolute;border:1px solid #d4d4d4;z-index:99;background:#fff;
      overflow-y:auto;max-height:250px;box-shadow:0 4px 6px rgba(0,0,0,0.1);
    `;
    inputElement.after(container);
    return container;
  }

  function populateList(arr, val, container) {
    const ucaseVal = val.toUpperCase();

    /*var sortedByLocality = arr.slice().sort((a, b) => {
      return a.locality.localeCompare(b.locality);
    });*/

    // Replace your current sortedByLocality with this:

    var sortedByLocality = (function () {
      const STATE_ORDER = ['NSW', 'VIC', 'QLD', 'SA', 'WA', 'TAS', 'NT', 'ACT'];
      const orderMap = Object.fromEntries(STATE_ORDER.map((s, i) => [s, i]));
      const norm = s => (s || '').toString().trim().toUpperCase();

      return arr.slice().sort((a, b) => {
        const aStateIdx = orderMap[norm(a.state)] ?? Number.MAX_SAFE_INTEGER;
        const bStateIdx = orderMap[norm(b.state)] ?? Number.MAX_SAFE_INTEGER;

        if (aStateIdx !== bStateIdx) return aStateIdx - bStateIdx;
        // same state: then sort by locality
        return String(a.locality || '').localeCompare(String(b.locality || ''));
      });
    })();

    // Prioritize startsWith matches, then includes
    const pcodeMatches = arr.filter(item =>
      String(item.pcode).startsWith(val) ||
      String(item.pcode).startsWith("0" + val)
    );
    const startsWithMatches = sortedByLocality.filter(item =>
      item.locality.toUpperCase().startsWith(ucaseVal)
    );
    const includesMatches = sortedByLocality.filter(item =>
      !item.locality.toUpperCase().startsWith(ucaseVal) &&
      item.locality.toUpperCase().includes(ucaseVal)
    );

    var topMatch = 8 + (val.length >= 3 ? 7 : 0);
    const matches = [...pcodeMatches, ...startsWithMatches, ...includesMatches].slice(0, topMatch);

    matches.forEach(item => container.appendChild(createListItem(item, val)));
  }

  function createListItem(data, val) {
    const item = document.createElement("DIV");
    item.style.cssText = "padding:10px;cursor:pointer;background:#fff;border-bottom:1px solid #d4d4d4;";
    const displayText = `${escapeHTMLchar(data.pcode)} ${escapeHTMLchar(data.locality).toUpperCase()}, ${escapeHTMLchar(data.state)}`.toUpperCase();
    item.innerHTML = highlightMatch(displayText, val);
    item.innerHTML += `
      <input type="hidden" class="selection"
        name="${escapeHTMLchar(data.combined)}"
        value="${displayText}"
        ${Object.keys(mapping).map(key => `data-${key}="${escapeHTMLchar(data[key])}"`).join(" ")}
      >
    `;
    item.addEventListener("mouseover", () => item.style.backgroundColor = "#eee");
    item.addEventListener("mouseout", () => item.style.backgroundColor = "#fff");
    item.addEventListener("click", function () {
      const inputElement = this.querySelector("input");
      setQuestionValue(qn_location, inputElement.value);
      Object.keys(mapping).forEach(key => setQuestionValue(mapping[key], inputElement.dataset[key]));
      closeAllLists();
    });
    return item;
  }

  function highlightMatch(text, val) {
    const index = text.indexOf(val.toUpperCase());
    return index === -1 ? text :
      `${text.substring(0, index)}<strong>${text.substring(index, index + val.length)}</strong>${text.substring(index + val.length)}`;
  }

  function closeAllLists(elmnt) {
    document.querySelectorAll(".autocomplete-items").forEach(list => {
      if (elmnt !== list && elmnt !== inp) list.remove();
    });
  }

  function filterState(arr, state) {
    const filtered = arr.filter(item => item.state === state);
    return filtered.length ? filtered : arr;
  }

  function setQuestionValue(qId, val) {
    Confirmit.page.getQuestion(qId).setValue(val);
  }

  function escapeHTMLchar(str) {
    return str.replace(/&/g, "&amp;")
      .replace(/</g, "&lt;")
      .replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;")
      .replace(/'/g, "&#39;");
  }

  document.addEventListener("click", e => closeAllLists(e.target));
}

